import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { moviesData } from '../data/moviesData';
import { getMovieDetails } from '../api/tmdb'; // 기존에 쓰시던 tmdb 연동 함수 import

function MovieDetail() {
  const { id } = useParams();
  
  // 로컬 데이터 및 API 데이터를 담을 상태 관리
  const [movie, setMovie] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchMovieData = async () => {
      setLoading(true);
      try {
        // 1. 만약 숫자로 된 TMDB ID 형태이거나 API 조산이 가능한 경우 처리
        // (기존 moviesData에 있는 문자열 키 형태인 경우 로컬 데이터 우선 매칭)
        const localMovie = moviesData[id];
        
        if (localMovie) {
          setMovie(localMovie);
          setLoading(false);
        } else {
          // 2. TMDB API를 통해 실시간 데이터 가져오기 (감독, 출연진, 이미지 포함)
          const apiData = await getMovieDetails(id);
          if (apiData) {
            setMovie({
              id: apiData.id,
              title: apiData.title || apiData.name,
              year: apiData.release_date ? apiData.release_date.split('-')[0] : '2026',
              age: apiData.adult ? '19+' : '15+',
              duration: apiData.runtime ? `${Math.floor(apiData.runtime / 60)}h ${apiData.runtime % 60}m` : '1h 50m',
              language: apiData.original_language ? apiData.original_language.toUpperCase() : 'KO',
              director: apiData.director || '감독 정보 없음',
              synopsis: apiData.overview || '줄거리 정보가 없습니다.',
              genres: apiData.genres ? apiData.genres.map(g => g.name) : ['드라마'],
              rating: apiData.vote_average ? apiData.vote_average.toFixed(1) : '9.5',
              poster: apiData.poster_path ? `https://image.tmdb.org/t/p/w500${apiData.poster_path}` : '/img/default_poster.jpg',
              backdrop: apiData.backdrop_path ? `https://image.tmdb.org/t/p/original${apiData.backdrop_path}` : null,
              gallery: apiData.images ? apiData.images.map(img => `https://image.tmdb.org/t/p/w500${img.file_path}`) : [],
              casts: apiData.cast ? apiData.cast.slice(0, 5).map(c => c.name).join(', ') : '출연진 정보 없음'
            });
          }
        }
      } catch (error) {
        console.error("영화 상세 정보를 불러오는 중 에러 발생:", error);
        // 에러 시 기본 로컬 첫 번째 데이터 Fallback
        setMovie(Object.values(moviesData)[0]);
      } finally {
        setLoading(false);
      }
    };

    fetchMovieData();
  }, [id]);

  if (loading) {
    return <div className="w-full min-h-screen bg-[#1c1c1e] text-white flex items-center justify-center text-xl font-bold">영화 정보를 불러오는 중입니다...</div>;
  }

  if (!movie) return <div className="text-white text-center py-20">영화를 찾을 수 없습니다.</div>;

  // 이미지 경로가 외부 URL(http...)인지 로컬 경로인지 판별하여 처리
  const getPosterSrc = (path) => {
    if (!path) return '';
    return path.startsWith('http') ? path : process.env.PUBLIC_URL + path;
  };

  return (
    <div className="w-full min-h-screen bg-[#1c1c1e] text-white font-sans relative pb-20">
      
      {/* 상단 백드롭(배경) 이미지 및 오버레이 */}
      <div className="absolute top-0 left-0 w-full h-[500px] overflow-hidden z-0">
        <img 
          src={getPosterSrc(movie.backdrop || movie.poster)} 
          alt="backdrop" 
          className="w-full h-full object-cover opacity-40 blur-md scale-105"
        />
        <div className="absolute inset-0 bg-gradient-to-b from-black/50 via-[#1c1c1e]/80 to-[#1c1c1e]"></div>
      </div>

      {/* 컨텐츠 메인 Wrapper */}
      <div className="relative z-10 max-w-5xl mx-auto pt-28 px-6">
        
        {/* 영화 타이틀 및 메타 정보 */}
        <div className="mb-8">
          <h1 className="text-4xl md:text-5xl font-black tracking-tight text-white mb-3 drop-shadow-lg">
            {movie.title}
          </h1>
          <p className="text-zinc-300 text-sm md:text-base font-bold mb-4">
            {movie.year} · {movie.age} · {movie.duration} · Language: {movie.language}
          </p>
          
          {/* 장르 뱃지 */}
          <div className="flex flex-wrap gap-2">
            {movie.genres?.map((genre, idx) => (
              <span key={idx} className="bg-zinc-800/80 backdrop-blur text-zinc-200 text-xs font-bold px-4 py-1.5 rounded-full border border-white/10 shadow-sm">
                {genre}
              </span>
            ))}
          </div>
        </div>

        {/* 관람객 평점 / 예매율 / 누적관객수 통계 바 */}
        <div className="w-full bg-zinc-900/85 backdrop-blur-md rounded-2xl border border-white/10 py-6 px-8 grid grid-cols-3 text-center mb-12 shadow-2xl">
          <div className="border-r border-white/10">
            <span className="text-xs font-bold text-zinc-400 block mb-1">실관람 평점</span>
            <span className="text-2xl md:text-3xl font-black text-white">
              {movie.rating || '9.5'}
            </span>
          </div>
          <div className="border-r border-white/10">
            <span className="text-xs font-bold text-zinc-400 block mb-1">예매율</span>
            <span className="text-2xl md:text-3xl font-black text-purple-400">
              1위 <span className="text-xs text-zinc-400 font-normal">(15.4%)</span>
            </span>
          </div>
          <div>
            <span className="text-xs font-bold text-zinc-400 block mb-1">누적관객수</span>
            <span className="text-xl md:text-2xl font-black text-white">
              8,199,271 <span className="text-xs font-normal text-zinc-400">명</span>
            </span>
          </div>
        </div>

        {/* 중단 상세 정보 영역 (포스터 + 영화정보 리스트) */}
        <div className="flex flex-col md:flex-row gap-10 items-start mb-16">
          
          {/* 좌측 포스터 */}
          <div className="w-full md:w-4/12 flex-shrink-0">
            <div className="w-full aspect-[3/4] rounded-2xl overflow-hidden shadow-2xl bg-zinc-800 border border-white/10">
              <img 
                src={getPosterSrc(movie.poster)} 
                alt={movie.title} 
                className="w-full h-full object-cover" 
              />
            </div>
          </div>

          {/* 우측 텍스트 정보 (원하시던 정갈한 리스트 스타일 및 큼직한 폰트) */}
          <div className="w-full md:w-8/12 space-y-6 bg-zinc-900/60 p-8 md:p-10 rounded-3xl border border-white/10 backdrop-blur-md shadow-2xl">
            
            {/* 섹션 제목 */}
            <h2 className="text-2xl font-extrabold text-white tracking-tight pb-2 border-b border-white/10">
              영화정보
            </h2>

            {/* 영화 정보 리스트 */}
            <div className="space-y-4 text-base md:text-lg">
              
              {/* 장르 */}
              <div className="flex items-start">
                <span className="text-zinc-400 font-bold w-20 flex-shrink-0">· 장르</span>
                <span className="text-zinc-100 font-medium">
                  {Array.isArray(movie.genres) ? movie.genres.join(' / ') : movie.genres}
                </span>
              </div>

              {/* 감독 */}
              <div className="flex items-start">
                <span className="text-zinc-400 font-bold w-20 flex-shrink-0">· 감독</span>
                <span className="text-zinc-100 font-medium underline underline-offset-4 decoration-zinc-500">
                  {movie.director}
                </span>
              </div>

              {/* 출연 */}
              <div className="flex items-start">
                <span className="text-zinc-400 font-bold w-20 flex-shrink-0">· 출연</span>
                <span className="text-zinc-100 font-medium leading-relaxed">
                  {movie.voiceCast || movie.casts || "출연진 정보 없음"}
                </span>
              </div>

            </div>

            {/* 구분선 */}
            <div className="w-full h-[1px] bg-white/10 my-4"></div>

            {/* 줄거리 */}
            <div className="space-y-2">
              <h3 className="text-lg font-bold text-white">· 줄거리</h3>
              <p className="text-base md:text-lg text-zinc-300 font-normal leading-relaxed tracking-wide text-justify">
                {movie.synopsis}
              </p>
            </div>

            {/* 예매하기 버튼 */}
            <div className="pt-4">
              <button className="w-full py-4 rounded-xl bg-[#503396] text-white font-black text-base hover:bg-[#3f2777] transition shadow-lg tracking-wide border border-purple-400/30">
                예매하기
              </button>
            </div>

          </div>

        </div>

        {/* 하단 갤러리 (스틸컷) 섹션 */}
        {movie.gallery && movie.gallery.length > 0 && (
          <div>
            <h3 className="text-sm font-black tracking-widest uppercase text-zinc-400 mb-6 text-center">
              G A L L E R Y
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {movie.gallery.map((imgSrc, idx) => (
                <div key={idx} className="rounded-2xl overflow-hidden bg-zinc-800 aspect-video border border-white/10 shadow-lg">
                  <img 
                    src={getPosterSrc(imgSrc)} 
                    alt={`gallery-${idx}`} 
                    className="w-full h-full object-cover hover:scale-105 transition duration-500" 
                  />
                </div>
              ))}
            </div>
          </div>
        )}

      </div>

    </div>
  );
}

export default MovieDetail;
